let state,docId='',baseline='',practiceId='';
const newPreviewToken=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
let previewToken=newPreviewToken(),previewTimer,studioEpoch=0,refreshSequence=0;
const facetKeys=['career_track','work_mode','seniority','employment_type','role_type','tenure_status','application_portal','research_class','institution_type','student_focus','university_id','university_state','job_state'];
let universityDirty=false;const dirtyUniversities=new Set();
function markUniversityDirty(el){const id=el.closest('[data-university]')?.dataset.university;if(id)dirtyUniversities.add(id);universityDirty=dirtyUniversities.size>0;}
const csrf=document.querySelector('meta[name=csrf]').content;
function notice(text,error=false){$('notice').setAttribute('role',error?'alert':'status');$('notice').hidden=false;$('notice').className=error?'error':'';$('notice').textContent=text;}
async function api(url,method='GET',data){const opts={method,headers:{'X-CSRF-Token':csrf}};if(data instanceof FormData)opts.body=data;else if(data!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data);}const r=await fetch(url,opts);let d;try{d=await r.json();}catch{throw Error('Server returned an unreadable response. Check the terminal.');}if(!r.ok)throw Error(d.error||r.statusText);return d;}
function action(id,fn){$(id).addEventListener('click',async e=>{e.preventDefault();const b=e.currentTarget;b.disabled=true;try{await fn();}catch(err){notice(err.message,true);}finally{b.disabled=false;}});}
function lines(id){return $(id).value.split('\n').map(x=>x.trim()).filter(Boolean);}
function options(list){return list.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');}
function openTab(id){document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));$('pageTitle').textContent=document.querySelector(`[data-tab="${id}"]`).textContent.replace(/^\d+\s*/,'').trim();if(id==='search'&&state)renderUniversities();}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>openTab(b.dataset.tab));
let searchDraft=[],deadlineAudio=null;
const heardDeadlines=new Set();
function deadlineState(j){const info=j.deadline_info||{date:'',kind:'unknown'};let days=null;if(info.date){const [y,m,d]=info.date.split('-').map(Number),today=new Date();days=Math.round((Date.UTC(y,m-1,d)-Date.UTC(today.getFullYear(),today.getMonth(),today.getDate()))/86400000);}const warn=state.settings.deadline_alerts&&['New','Shortlist','Drafting','Ready to Submit'].includes(j.status);return {...info,days,urgent:warn&&days!==null&&days>=0&&days<=state.settings.deadline_warning_days,passed:warn&&days!==null&&days<0};}
function deadlineMatches(j){const d=deadlineState(j),v=$('deadlineFilter').value,from=$('deadlineFrom').value,to=$('deadlineTo').value;if((from||to)&&(!d.date||(from&&d.date<from)||(to&&d.date>to)))return false;if(!v)return true;if(v==='soon')return d.days!==null&&d.days>=0&&d.days<=state.settings.deadline_warning_days;if(v==='today')return d.days===0;if(v==='upcoming')return d.days!==null&&d.days>=0;if(v==='passed')return d.days!==null&&d.days<0;if(['unknown','rolling','review'].includes(v))return d.kind===v;return d.days!==null&&d.days>=0&&d.days<=Number(v);}
function deadlineBadge(j){const d=deadlineState(j);return d.urgent?`<span class="deadline-badge">⚠ ${d.days===0?'Due today':'Due in '+d.days+' day'+(d.days===1?'':'s')}</span>`:d.passed?`<span class="deadline-badge">Deadline passed · ${Math.abs(d.days)} day(s) ago</span>`:'';}
function renderDeadlineAlarm(){const due=state.jobs.filter(j=>deadlineState(j).urgent),today=due.filter(j=>deadlineState(j).days===0).length;const box=$('deadlineAlarm');box.hidden=!due.length;box.textContent=due.length+' unsubmitted application(s) due within '+state.settings.deadline_warning_days+' days'+(today?' · '+today+' due today':'')+'. Use the Approaching deadline filter to review them. Check the posting’s cutoff time.';if(deadlineAudio&&!document.hidden){const date=new Date().toLocaleDateString();const fresh=due.filter(j=>!heardDeadlines.has((state.active_workspace||'local')+':'+j.id+':'+j.deadline+':'+date));if(fresh.length){for(const j of fresh)heardDeadlines.add((state.active_workspace||'local')+':'+j.id+':'+j.deadline+':'+date);const osc=deadlineAudio.createOscillator(),gain=deadlineAudio.createGain();osc.connect(gain);gain.connect(deadlineAudio.destination);osc.frequency.value=660;gain.gain.value=.06;osc.start();osc.stop(deadlineAudio.currentTime+.25);}}}
submitForm('deadlineSettings',async()=>{await api('/api/settings','POST',{deadline_alerts:$('deadlineAlerts').checked,deadline_warning_days:Number($('deadlineDays').value)});await refresh();notice('Deadline alert settings saved. Alarms run while the app is open.');});
action('deadlineSound',async()=>{if(deadlineAudio){await deadlineAudio.close();deadlineAudio=null;$('deadlineSound').textContent='Enable sound for this tab';return;}const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('This browser does not support sound alerts. Visual alerts remain available.');deadlineAudio=new Audio();await deadlineAudio.resume();$('deadlineSound').textContent='Mute deadline sound';renderDeadlineAlarm();});
function defaultSearchDraft(){const rows=[];const add=(kind,value,label=value,enabled=true)=>rows.push({id:newPreviewToken(),kind,value,label,enabled});for(const q of state.settings.queries)add('job',q);for(const [name,cfg] of Object.entries(state.settings.sources))add('board',name,name,cfg.enabled);for(const r of state.settings.regions)add('state',r);for(const c of state.settings.countries)add('country',c);for(const url of state.settings.custom_urls)add('url',url);for(const u of state.universities)add('university',u.id,u.name,!!(u.screen&&u.career_verified));return rows;}
function addUniversityChoices(){for(const u of state.universities){if(!searchDraft.some(t=>t.kind==='university'&&(t.value===u.id||t.value.toLowerCase()===u.name.toLowerCase())))searchDraft.push({id:newPreviewToken(),kind:'university',value:u.id,label:u.name,enabled:false});}}
function renderSearchTargets(){
 const q=$('targetFilter').value.trim().toLowerCase(),labels={board:'Job boards',university:'Universities',job:'Job keywords / titles',state:'States / regions',country:'Countries',role:'Job roles',tenure:'Tenure status',keyword:'Required keywords',url:'Other websites'};
 $('searchTargetList').innerHTML=Object.entries(labels).map(([kind,label])=>{const rows=searchDraft.filter(t=>t.kind===kind).filter(t=>{const u=state.universities.find(u=>u.id===t.value);return (t.label+' '+t.value+' '+(u?.state||'')).toLowerCase().includes(q)});if(!rows.length)return '';return `<details class="search-group" open><summary>${esc(label)} (${rows.length})</summary>${rows.map(t=>{const u=t.kind==='university'?state.universities.find(u=>u.id===t.value||u.name.toLowerCase()===t.value.toLowerCase()):null;return `<div class="row"><label class="inline"><input type="checkbox" data-search-target="${esc(t.id)}" ${t.enabled?'checked':''}>${esc(t.kind)}: ${esc(t.label)} <small>${u?esc(u.state||'State unknown')+(u.career_verified?' · career page confirmed':' · confirm career page below'):t.label!==t.value?esc(t.value):''}</small></label>${['board','university','url'].includes(t.kind)?`<label class="inline">Result limit<input type="number" min="1" max="1000" data-target-limit="${esc(t.id)}" value="${t.limit??''}" placeholder="Global" aria-label="Result limit for ${esc(t.label)}"></label>`:''}<button type="button" data-remove-target="${esc(t.id)}">Remove</button></div>`}).join('')}</details>`}).join('')||'<p>No matching targets. Add a target above.</p>';targetSuggestions();
}
$('targetFilter').oninput=renderSearchTargets;
