function targetSuggestions(){if(!state)return;const k=$('targetKind').value;const values=k==='board'?Object.keys(state.settings.sources):k==='university'?state.universities.map(u=>u.name):k==='track'?state.facets_options.tracks:k==='work_mode'?state.facets_options.work_modes:k==='seniority'?state.facets_options.seniority:k==='role'?state.facets_options.roles:k==='tenure'?state.facets_options.tenures:k==='state'?['NY','NJ','CA','MA','TX','PA']:k==='country'?['United States','Canada','United Kingdom']:[];$('targetSuggestions').innerHTML=values.map(v=>`<option value="${esc(v)}">`).join('');$('targetHelp').textContent=k==='board'?'Select an existing board name, or enter a full board URL. Custom board URLs may contain {query} and {location}.':k==='university'?'Select an employer or university from the directory. Confirm its career page there before running.':k==='url'?'Enter a full https:// website URL to screen.':k==='job'?'Enter job keywords, e.g. robotics or computer science. All words in one entry must appear in the posting; multiple checked entries are alternatives.':'Enter a value or choose a suggested option, then save the checklist.';}
$('targetKind').onchange=targetSuggestions;
$('searchTargetList').onchange=e=>{const t=searchDraft.find(t=>t.id===e.target.dataset.searchTarget);if(t)t.enabled=e.target.checked;const limit=searchDraft.find(t=>t.id===e.target.dataset.targetLimit);if(limit){if(e.target.value==='')delete limit.limit;else limit.limit=Number(e.target.value);}};
$('searchTargetList').onclick=e=>{const id=e.target.dataset.removeTarget;if(id){searchDraft=searchDraft.filter(t=>t.id!==id);renderSearchTargets();}};
submitForm('searchTargetAdd',async()=>{const kind=$('targetKind').value,raw=$('targetValue').value.trim(),uni=kind==='university'?state.universities.find(u=>u.name.toLowerCase()===raw.toLowerCase()||u.id===raw):null;const value=uni?uni.id:raw,label=$('targetLabel').value.trim()||uni?.name||raw;if(!value)throw Error('Enter a search value');if(searchDraft.some(t=>t.kind===kind&&t.value.toLowerCase()===value.toLowerCase()))throw Error('This target is already in the checklist');searchDraft.push({id:newPreviewToken(),kind,value,label,enabled:true});$('targetValue').value='';$('targetLabel').value='';renderSearchTargets();notice('Added to checklist. Click Save selections to keep it for later searches.');});
