function fillSettings(){const s=state.settings;$('deadlineAlerts').checked=s.deadline_alerts;$('deadlineDays').value=s.deadline_warning_days;$('savedSearchEnabled').checked=s.saved_search_enabled;searchDraft=structuredClone(s.search_targets.length?s.search_targets:defaultSearchDraft());addUniversityChoices();$('selectedPageLimit').value=s.max_pages;$('selectedResultLimit').value=s.search_result_limit;renderSearchTargets();$('autoUniversityDiscovery').checked=s.auto_university_discovery;$('documentsRoot').value=s.documents_root||'';for(const k of ['queries','excluded_keywords','required_keywords','preferred_keywords','countries','regions','preferred_job_types','excluded_employers','custom_urls'])$(k).value=s[k].join('\n');for(const k of ['minimum_salary','currency','max_pages','provider','model','ollama_url','discovery_mode'])$(k).value=s[k];for(const k of ['network_enabled','ai_enabled','exclude_unknown_salary','exclude_unknown_location','browser_render','show_browser'])$(k).checked=s[k];$('profileName').value=s.profile.full_name||'';$('profileFacts').value=s.profile.facts||JSON.stringify(s.profile,null,2);$('profileVerified').checked=!!s.profile.verified;$('sourceSettings').innerHTML=Object.entries(s.sources).map(([n,v])=>`<div class="source-row" data-source="${esc(n)}"><label class="inline"><input type="checkbox" class="sourceEnabled" ${v.enabled?'checked':''}>${esc(n)}</label><input class="sourceLimit" type="number" min="1" max="100" value="${v.limit}" aria-label="${esc(n)} result limit"><input class="sourceUrl" value="${esc(v.url)}" aria-label="${esc(n)} search URL"></div>`).join('');$('pdfEngine').value=s.pdf_engine;$('pdfBrowserFallback').checked=s.pdf_browser_fallback;$('pdfRemoteConsent').checked=s.pdf_remote_consent;$('storageMode').value=s.storage.mode;$('storageDestination').value=s.storage.destination;$('storageAuto').checked=s.storage.auto_sync;fillRules();}
function fillRules(){const cat=$('ruleCategory').value;if(!cat)return;const r=state.settings.rules[cat];$('ruleDos').value=r.dos||'';$('ruleDonts').value=r.donts||'';$('rulePrompt').value=r.prompt||'';$('ruleTemplate').value=state.settings.templates[cat]||'';}
async function refresh(settings=false){const ticket=++refreshSequence,fresh=await api('/api/state');if(ticket!==refreshSequence)return;state=fresh;$('connection').textContent=(state.settings.network_enabled?'Network allowed':'Network off')+' · '+(state.settings.ai_enabled?'AI enabled':'AI off');const selected={};document.querySelectorAll('.jobSelect').forEach(el=>selected[el.id]=el.value);const jobs=state.jobs.filter(j=>j.status!=='Ignored');document.querySelectorAll('.jobSelect').forEach(el=>{el.innerHTML='<option value="">Choose a job…</option>'+jobs.map(j=>`<option value="${j.id}">${esc(j.institution)} · ${esc(j.title)}</option>`).join('');el.value=selected[el.id]||'';});for(const id of ['docCategory','ruleCategory']){const old=$(id).value;$(id).innerHTML=options(state.categories);if(state.categories.includes(old))$(id).value=old;}const oldMem=$('memoryCategory').value;$('memoryCategory').innerHTML=options(['general','interview','career','presentation',...state.categories]);$('memoryCategory').value=oldMem||'general';if(!$('editStatus').options.length){$('editStatus').innerHTML=options(state.statuses);$('statusFilter').innerHTML+=options(state.statuses);}const source=$('sourceFilter').value;$('sourceFilter').innerHTML='<option value="">All sources</option>'+options([...new Set(state.jobs.flatMap(j=>j.sources||[]))]);$('sourceFilter').value=source;fillCardFilters();if(settings)fillSettings();else {addUniversityChoices();renderSearchTargets();}syncJobStatuses();renderUniversities();renderJobs();renderMemory();renderHistory();renderVersions();renderTeam();if(window.careerRefresh)window.careerRefresh();if(window.captureRefresh)window.captureRefresh();if(window.searchWorkspaceRefresh)window.searchWorkspaceRefresh();if(window.packagesRefresh)window.packagesRefresh();if(window.workbenchRefresh)window.workbenchRefresh();if(window.journeyRefresh)window.journeyRefresh();if(window.schedulerRefresh)window.schedulerRefresh();if(window.mailRefresh)window.mailRefresh();if(window.suiteRefresh)window.suiteRefresh();}
function safeLink(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)&&u.hostname!=='manual-entry.local'?u.href:'';}catch{return '';}}
function fitHtml(j){const f=j.fit;if(!f)return '';return `<div class="fit-details"><strong>Why this may fit</strong><p>${f.matched_topics} of ${f.posting_topics} detected posting topics appear in the profile. Preferred-keyword coverage: ${j.assessment.keyword_match==null?'not configured':j.assessment.keyword_match+'%'}. Recalculated from saved text.</p>${!f.verified_profile?'<small class="warning">Verify your profile before relying on these matches.</small>':''}<ul>${f.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><details><summary>Evidence and unknowns</summary>${f.evidence.map(x=>`<div class="fit-evidence"><strong>${esc(x.skill)}</strong><small>Profile: ${esc(x.profile_evidence)}</small><small>Posting: ${esc(x.job_evidence)}</small></div>`).join('')}<p>Posting topics not established by your profile: ${esc(f.not_in_profile.join(', ')||'None detected')}</p><small>${esc(f.note)}</small></details></div>`;}
function fillCardFilters(){for(const key of facetKeys){const el=$('filter_'+key),old=el.value;const values=[...new Set((key==='university_id'?state.universities.map(u=>u.id):state.jobs.map(j=>j.facets[key])).filter(Boolean))].sort((a,b)=>key==='university_id'?(state.universities.find(u=>u.id===a)?.name||a).localeCompare(state.universities.find(u=>u.id===b)?.name||b):a.localeCompare(b));if(old&&!values.includes(old))values.push(old);el.innerHTML='<option value="">All</option>'+values.map(v=>`<option value="${esc(v)}">${esc(key==='university_id'?(state.universities.find(u=>u.id===v)?.name||v):v)}</option>`).join('');el.value=old;}}
action('resetCardFilters',()=>{$('postingFilter').value='';$('deadlineFilter').value='';$('deadlineFrom').value='';$('deadlineTo').value='';$('cardSort').value='fit';for(const k of facetKeys)$('filter_'+k).value='';$('jobSearch').value='';$('sourceFilter').value='';$('eligibleOnly').checked=false;$('statusFilter').value='active';renderJobs();});
function universitySelect(field,choices,value){return `<select data-ufield="${field}">${choices.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select>`;}
function renderUniversities(){
 if(universityDirty||$('search').hidden)return;const opened=new Set(Array.from(document.querySelectorAll('[data-university][open]'),x=>x.dataset.university));const q=$('universitySearch').value.toLowerCase();const rows=state.universities.filter(u=>(u.name+' '+u.state).toLowerCase().includes(q));
 $('universityList').innerHTML='<p>'+rows.length+' institutions. Showing up to 50; search to narrow the list.</p>'+rows.slice(0,50).map(u=>`<details class="panel" data-university="${u.id}" ${opened.has(u.id)?'open':''}><summary><strong>${esc(u.name)}</strong> · ${esc(u.state||'State unknown')} · ${esc(u.research_class)} · ${u.job_count} positions · ${esc(u.discovery_status)}</summary><form data-university-form="${u.id}"><div class="grid"><label>State / region<input data-ufield="state" value="${esc(u.state)}"></label><label>Country<input data-ufield="country" value="${esc(u.country)}"></label><label>Official website<input data-ufield="website" type="url" value="${esc(u.website)}"></label><label>Career page<input data-ufield="career_url" type="url" value="${esc(u.career_url)}"></label><label>Employer type${universitySelect('organization_type',state.facets_options.organizations,u.organization_type||'Unknown')}</label><label>Research classification${universitySelect('research_class',state.facets_options.research,u.research_class)}</label><label>Institution type${universitySelect('institution_type',state.facets_options.types,u.institution_type)}</label><label>Student focus${universitySelect('student_focus',state.facets_options.levels,u.student_focus)}</label></div><label class="inline"><input data-ufield="career_verified" type="checkbox" ${u.career_verified?'checked':''}> I reviewed this career page and confirmed it belongs to this institution</label><label class="inline"><input data-ufield="screen" type="checkbox" ${u.screen?'checked':''}> Include in Search universities</label><div class="toolbar"><button>Save university</button><button type="button" data-discover="${u.id}" ${u.discovery_status==='queued'?'disabled':''}>Find career page with AI / web</button><button type="button" data-university-jobs="${u.id}">Show positions</button></div></form><p>Save edits before discovery. Confirm the institution/campus and career URL before enabling screening.</p>${u.error?`<details><summary>Discovery details</summary><pre>${esc(u.error)}</pre></details>`:''}${(u.suggestions||[]).map(c=>`<div class="row"><strong>${esc(c.title||'Career-page candidate')}</strong> · unverified<br><a href="${esc(safeLink(c.url))}" target="_blank" rel="noopener noreferrer">${esc(c.url)}</a><p>${esc(c.reason)}</p><p>${esc(c.evidence)}</p><button data-use-career="${esc(c.url)}">Use this URL for review</button></div>`).join('')}</details>`).join('');
}
