function renderJobs(){renderDeadlineAlarm();const q=$('jobSearch').value.toLowerCase(),status=$('statusFilter').value,source=$('sourceFilter').value;const active=state.jobs.filter(j=>!['Ignored','Archived','Rejected','Withdrawn'].includes(j.status));$('metrics').innerHTML=[[active.length,'Active opportunities'],[state.jobs.filter(j=>j.status==='Submitted').length,'Applications submitted'],[state.jobs.filter(j=>j.status==='Interviewing').length,'Interviewing'],[state.jobs.filter(j=>j.status==='Ignored').length,'Permanently ignored']].map(([n,t])=>`<div class="metric"><strong>${n}</strong><span>${t}</span></div>`).join('');const jobs=state.jobs.filter(j=>(status==='all'||(status==='active'?active.includes(j):j.status===status))&&(!source||(j.sources||[]).includes(source))&&(!q||[j.title,j.institution,j.description].join(' ').toLowerCase().includes(q))&&postingMatches(j)&&deadlineMatches(j)&&facetKeys.every(k=>!$('filter_'+k).value||j.facets[k]===$('filter_'+k).value)&&(!$('eligibleOnly').checked||j.assessment.eligible));jobs.sort((a,b)=>{if($('cardSort').value==='action')return (a.next_action_due||'9999').localeCompare(b.next_action_due||'9999');if($('cardSort').value==='deadline'){const rank=j=>{const d=deadlineState(j).days;return d===null?1e9:d>=0?d:100000+Math.abs(d);};return rank(a)-rank(b);}return Number(b.assessment.preferred_type)-Number(a.assessment.preferred_type)||(b.fit.topic_coverage??-1)-(a.fit.topic_coverage??-1);});$('filteredCount').textContent=jobs.length+' of '+state.jobs.length+' positions shown';$('jobList').innerHTML=jobs.length?jobs.map(j=>`<article class="card ${deadlineState(j).urgent?'deadline-urgent':deadlineState(j).passed?'deadline-passed':''}">${deadlineBadge(j)}${postingBadge(j)}<div class="card-top"><span class="badge">${esc(j.status)}</span><span class="match">${j.fit.topic_coverage==null?'Coverage unavailable':j.fit.topic_coverage+'% topic coverage'}</span></div><h3>${esc(j.title)}</h3><p><strong>${esc(j.institution)}</strong><br>${esc(j.location||'Location unknown')} · ${esc((j.sources||[]).join(', '))}</p><p><span class="badge">${esc(j.facets.career_track)}</span> ${esc(j.facets.work_mode)} · ${esc(j.facets.seniority)}<br>${esc(j.facets.role_type)}${j.facets.career_track==='Academic'?' · '+esc(j.facets.tenure_status):''}<br>Apply via: ${esc(j.facets.application_portal)}${j.facets.career_track==='Academic'?'<br>University: '+esc(j.facets.research_class)+' · '+esc(j.facets.institution_type):''}</p><p>Deadline: ${esc(j.deadline||'Unknown')}<br>Salary: ${esc(j.salary||'Unknown')}</p>${j.assessment.exclusions.length?`<p class="warning">${esc(j.assessment.exclusions.join('; '))}</p>`:''}${j.needs_review?'<p class="warning">Extracted page: verify employer and title before applying.</p>':''}${j.next_action?`<p>Next: ${esc(j.next_action)}${j.next_action_due?' · Due '+esc(j.next_action_due):''}</p>`:''}${fitHtml(j)}<div class="toolbar">${safeLink(j.apply_url||j.url)?`<a class="button primary" href="${esc(safeLink(j.apply_url||j.url))}" target="_blank" rel="noopener noreferrer">${j.apply_url?'Apply':'Apply / view posting'}</a>`:''}<select class="quick-status" data-quick-status="${j.id}" aria-label="Application status">${state.statuses.map(st=>`<option ${st===j.status?'selected':''}>${esc(st)}</option>`).join('')}</select><button data-posting="${j.id}">Posting check / changes</button><button data-edit="${j.id}">Details / edit</button><button data-studio="${j.id}">Documents</button><button data-journey-open="${j.id}">Timeline / interviews</button><button data-strategy="${j.id}">Role strategy</button><button data-delete-job="${j.id}">Delete job</button><button data-ignore="${j.id}">${j.status==='Ignored'?'Restore':'Ignore forever'}</button></div></article>`).join(''):'<div class="panel">No jobs match this view. Change filters, import a database, or add a job.</div>';}
$('jobList').onclick=async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.edit)await editJob(b.dataset.edit);if(b.dataset.studio){clearStudio();$('studioJob').value=b.dataset.studio;openTab('studio');syncJobStatuses();renderVersions();if(window.loadRequirements)window.loadRequirements();if(window.loadPackages)window.loadPackages();}if(b.dataset.ignore){const j=state.jobs.find(x=>x.id===b.dataset.ignore);await api('/api/jobs/'+j.id+(j.status==='Ignored'?'/restore':'/ignore'),'POST',{});await refresh();notice(j.status==='Ignored'?'Job restored.':'Opening ignored. Known source URLs will stay suppressed. Review possible duplicates to connect other versions.');}}catch(err){notice(err.message,true);}};
for(const id of ['deadlineFilter','deadlineFrom','deadlineTo','cardSort','jobSearch','statusFilter','sourceFilter','eligibleOnly',...facetKeys.map(k=>'filter_'+k)])$(id).addEventListener('input',renderJobs);
