const fields={Track:'career_track',Work:'work_mode',Level:'seniority',Period:'salary_period',Due:'next_action_due',Priority:'priority',Role:'role_type',Tenure:'tenure_status',Portal:'application_portal',Institution:'institution',Title:'title',Url:'url',Apply:'apply_url',Department:'department',Location:'location',Country:'country',Region:'region',Salary:'salary',SalaryMin:'salary_min',Currency:'currency',Deadline:'deadline',Type:'job_type',Status:'status',Required:'required_documents',Description:'description',Notes:'notes',Next:'next_action',Contacts:'contacts'};
async function editJob(id=''){for(const [id,key] of [['editRole','roles'],['editTenure','tenures'],['editPortal','portals']])$(id).innerHTML='<option value="">Automatic from posting</option>'+options(state.facets_options[key]);const j=id?await api('/api/jobs/'+id):{status:'New'};$('editJobId').value=id;for(const [k,f]of Object.entries(fields))$('edit'+k).value=typeof j[f]==='object'?JSON.stringify(j[f]):j[f]??({work_mode:'Unknown',seniority:'Unknown',salary_period:'Annual',priority:'Normal'}[f]||'');for(const [el,key]of Object.entries({Salary:'salary',Currency:'currency',Startup:'startup',Load:'workload',Date:'decision_date',Notes:'notes'}))$('offer'+el).value=j.offer?.[key]||'';$('jobSourceUrls').innerHTML=(j.source_urls||[]).map(u=>`<p><a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(u)}</a></p>`).join('');$('notifyStaff').checked=true;$('notifyRecipients').textContent='Recipients: '+(state.members.filter(m=>m.id!==state.account?.id).map(m=>m.username).join(', ')||'No other collaborators yet');$('jobHistory').innerHTML='';if(id){const history=await api('/api/jobs/'+id+'/history');$('jobHistory').innerHTML=history.map(h=>`<details class="row"><summary>${esc(h.created)} · ${esc(h.data.actor||h.kind)}</summary><pre>${esc(JSON.stringify(h.data,null,2))}</pre></details>`).join('')||'<p>No edits yet.</p>';}$('jobDialog').showModal();}
action('newJob',()=>editJob());action('closeJob',()=>{$('jobDialog').close();});
$('jobForm').onsubmit=async e=>{e.preventDefault();try{const d={};for(const[k,f]of Object.entries(fields))d[f]=$('edit'+k).value;d.salary_min=d.salary_min===''?null:Number(d.salary_min);d.offer={};for(const[el,key]of Object.entries({Salary:'salary',Currency:'currency',Startup:'startup',Load:'workload',Date:'decision_date',Notes:'notes'}))d.offer[key]=$('offer'+el).value;d.notify_staff=$('notifyStaff').checked;const id=$('editJobId').value;if(!d.url&&!id)delete d.url;await api('/api/jobs'+(id?'/'+id:''),id?'PATCH':'POST',d);$('jobDialog').close();await refresh();notice('Job saved.');}catch(err){notice(err.message,true);alert(err.message);}};
$('searchForm').onsubmit=async e=>{e.preventDefault();try{const d={};for(const k of ['queries','excluded_keywords','required_keywords','preferred_keywords','countries','regions','preferred_job_types','excluded_employers','custom_urls'])d[k]=lines(k);for(const k of ['exclude_unknown_salary','exclude_unknown_location','browser_render','show_browser'])d[k]=$(k).checked;d.discovery_mode=$('discovery_mode').value;d.minimum_salary=Number($('minimum_salary').value);d.currency=$('currency').value.trim().toUpperCase();d.max_pages=Number($('max_pages').value);d.sources={};document.querySelectorAll('[data-source]').forEach(row=>d.sources[row.dataset.source]={enabled:row.querySelector('.sourceEnabled').checked,limit:Number(row.querySelector('.sourceLimit').value),url:row.querySelector('.sourceUrl').value});await api('/api/settings','POST',d);await refresh(true);notice('Search controls saved and active.');}catch(err){notice(err.message,true);}};
async function runTask(url,data){const workspace=state?.active_workspace;const {task_id}=await api(url,'POST',data);notice('Working… You can use other sections while this runs.');for(;;){await new Promise(r=>setTimeout(r,1200));if(state?.active_workspace!==workspace)throw Error('Workspace changed. This task continues in its original workspace; reopen it there.');const t=await api('/api/tasks/'+task_id);if(t.log?.length)notice(t.log.slice(-4).join('\n'));if(t.state==='failed'||t.state==='interrupted'){await refresh();throw Error(t.error||'Task interrupted by restart');}if(t.state==='done'){await refresh();notice('Completed.');return t.result;}}}
document.querySelectorAll('[data-run]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await runTask('/api/search',{kind:b.dataset.run});notice(`Search completed: ${r.added} added, ${r.duplicate} already known, ${r.ignored} ignored, ${r.filtered} filtered. ${r.errors.length} source/page errors; see run history.`);}catch(err){notice(err.message,true);}finally{b.disabled=false;}});
action('loadDuplicates',async()=>{const d=await api('/api/duplicates');$('duplicateList').innerHTML=d.length?d.map(p=>`<div class="row"><strong>${esc(p.institution)}</strong><p>${esc(p.title_a)} ↔ ${esc(p.title_b)}</p><div class="toolbar"><button data-review="${p.a}">Open first</button><button data-review="${p.b}">Open second</button><button data-merge="${p.a}" data-other="${p.b}">Merge into first</button></div></div>`).join(''):'<p>No similar employer/title pairs found.</p>';});
$('duplicateList').onclick=async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.review)await editJob(b.dataset.review);if(b.dataset.merge&&confirm('Merge these records? The first status is kept, except Ignored takes priority. A backup is created.')){await api('/api/merge','POST',{keep:b.dataset.merge,other:b.dataset.other});await refresh();$('loadDuplicates').click();}}catch(err){notice(err.message,true);}};
function syncJobStatuses(){for(const prefix of ['studio','interview']){const job=state.jobs.find(j=>j.id===$(prefix+'Job').value);$(prefix+'Status').innerHTML=options(state.statuses);$(prefix+'Status').value=job?.status||'New';$(prefix+'Status').disabled=!job;$(prefix+'StatusSave').disabled=!job;}}
async function discardStudioPreview(){const old=previewToken;previewToken=newPreviewToken();studioEpoch++;clearTimeout(previewTimer);previewAgain=false;await api('/api/previews/'+old,'DELETE');$('pdfPreview').removeAttribute('src');$('docLinks').innerHTML='';$('pdfStatus').textContent='Temporary preview cleared. Editor text is still here; approved files are preserved.';}
action('discardPreview',discardStudioPreview);
for(const prefix of ['studio','interview'])action(prefix+'StatusSave',async()=>{const jid=$(prefix+'Job').value,status=$(prefix+'Status').value;if(!jid)throw Error('Choose a job');await api('/api/jobs/'+jid,'PATCH',{status,notify_staff:true});if(jid===$('studioJob').value&&['Submitted','Interviewing','Offer','Rejected','Withdrawn','Archived','Ignored'].includes(status))await discardStudioPreview();await refresh();notice('Job status updated to '+status+'.');});
function clearStudio(){if(window.clearDocumentChecks)window.clearDocumentChecks();const old=previewToken;previewToken=newPreviewToken();studioEpoch++;clearTimeout(previewTimer);api('/api/previews/'+old,'DELETE').catch(()=>{});docId='';baseline='';$('latexEditor').value='';$('promptEditor').value='';$('pdfPreview').removeAttribute('src');$('docLinks').innerHTML='';$('pdfStatus').textContent='Preview PDF uses temporary files. Save & approve keeps both PDF and LaTeX.';}
