async function generate(manual){const jid=$('studioJob').value,epoch=studioEpoch;if(!jid)throw Error('Choose a target job');const r=await runTask('/api/documents/generate',{job_id:jid,category:$('docCategory').value,notes:$('docNotes').value,draft:$('latexEditor').value,mode:$('docMode').value,manual});if(epoch!==studioEpoch)return;$('latexEditor').value=r.content;$('promptEditor').value=r.prompt;baseline=r.content;docId='';if(!manual)await previewCurrent();notice(manual?'Prompt prepared. Paste the resulting LaTeX into the editor.':'Draft generated temporarily. Review, then Save & approve.');}
