function docLinks(){if(!docId)return;if(window.loadRequirements)window.loadRequirements().catch(e=>notice(e.message,true));if(window.loadSavedChecks)window.loadSavedChecks(docId);$('pdfPreview').src='/api/documents/'+docId+'/view';$('pdfStatus').textContent='Approved/saved version. Editing creates a temporary preview until Save & approve.';$('docLinks').innerHTML=`<p><a href="/api/documents/${docId}/tex">Download LaTeX version</a> · <a href="/api/documents/${docId}/log">Download compiler log</a> · <a href="/api/documents/${docId}/view" target="_blank" rel="noopener">Open PDF in new tab</a> · <a href="/api/documents/${docId}/preview" target="_blank" rel="noopener">Plain-text fallback (formatting lost)</a></p>`;}
let previewBusy=false,previewAgain=false;
function currentDocument(){return {job_id:$('studioJob').value,category:$('docCategory').value,content:$('latexEditor').value,prompt:$('promptEditor').value,baseline,review_ack:$('reviewWarnings').checked};}
async function previewCurrent(){
 if(previewBusy){previewAgain=true;return;}const token=previewToken,d=currentDocument();if(!d.job_id)throw Error('Choose a job');if(!d.content.trim())throw Error('Enter LaTeX first');previewBusy=true;
 $('pdfStatus').textContent='Compiling temporary preview…';
 try{const r=await runTask('/api/previews/'+token,d);if(token!==previewToken){await api('/api/previews/'+token,'DELETE');return;}if(d.content!==$('latexEditor').value){previewAgain=true;return;}
 $('pdfPreview').src='/api/previews/'+token+'/pdf?v='+Date.now();$('pdfStatus').textContent='Temporary preview only. '+(r.approximate?'Approximate browser rendering. ':'')+'Save & approve to keep both files.';
 if(window.renderDocumentChecks)window.renderDocumentChecks(r.checks);
 $('docLinks').innerHTML=`<a href="/api/previews/${token}/log" target="_blank">Preview compiler log</a>`;
 }catch(e){if(token===previewToken){$('pdfPreview').removeAttribute('src');$('pdfStatus').textContent='Preview failed. Nothing was approved or saved. '+e.message;$('docLinks').innerHTML=`<a href="/api/previews/${token}/log" target="_blank">Preview compiler log</a>`;}throw e;
 }finally{previewBusy=false;if(previewAgain){previewAgain=false;if($('latexEditor').value.trim())previewCurrent().catch(e=>notice(e.message,true));}}
}
action('previewDoc',previewCurrent);
action('approveDoc',async()=>{clearTimeout(previewTimer);const token=previewToken,d=currentDocument();if(!d.job_id)throw Error('Choose a job');const r=await runTask('/api/previews/'+token+'/approve',d);if(token===previewToken){docId=r.id;docLinks();$('pdfStatus').textContent='Approved PDF and LaTeX saved: '+r.filename;previewToken=newPreviewToken();}await refresh();notice('PDF and LaTeX approved and saved in '+r.folder);});
$('latexEditor').addEventListener('input',()=>{if(window.clearDocumentChecks)window.clearDocumentChecks();clearTimeout(previewTimer);$('pdfStatus').textContent='Edits are not saved. Updating temporary preview…';previewTimer=setTimeout(()=>previewCurrent().catch(e=>notice(e.message,true)),1400);});
