$('databaseUpload').onchange=async()=>{try{const f=$('databaseUpload').files[0];if(!f)return;const d=new FormData();d.append('file',f);const r=await runTask('/api/import',d);notice('Import report:\n'+JSON.stringify(r,null,2));}catch(err){notice(err.message,true);}};
action('backupBtn',async()=>{const r=await fetch('/api/backup',{method:'POST',headers:{'X-CSRF-Token':csrf}});if(!r.ok)throw Error('Backup failed');const u=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=u;a.download='job_coach_backup.db';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);});

function renderTeam(){const u=state.account;$('currentUser').textContent=u?u.username:'';$('accountUsername').value=u?.username||'';$('workspaceSelect').innerHTML=state.workspaces.map(w=>`<option value="${w.id}">${esc(w.label)} · ${esc(w.role)}</option>`).join('');$('workspaceSelect').value=state.active_workspace;$('createUserPanel').hidden=!u?.admin;$('inboxBadge').textContent=state.notifications.filter(n=>!n.seen).length||'';$('notificationList').innerHTML=state.notifications.map(n=>`<div class="row ${n.seen?'':'unread'}"><strong>${esc(n.actor)}</strong> · ${esc(n.message)}<small> ${esc(n.created)}</small><div class="toolbar"><button data-notification="${n.id}" data-space="${n.space}" data-job="${n.job_id}">Open change</button><button data-read="${n.id}">Mark read</button></div></div>`).join('')||'<p>No notifications yet.</p>';$('memberList').innerHTML=state.members.map(m=>`<p>${esc(m.username)} · ${esc(m.role)}</p>`).join('');}
$('jobList').addEventListener('change',async e=>{const id=e.target.dataset.quickStatus;if(!id)return;try{await api('/api/jobs/'+id,'PATCH',{status:e.target.value,notify_staff:true});await refresh();notice('Status saved and collaborators notified.');}catch(err){notice(err.message,true);}});
$('workspaceSelect').onchange=async()=>{try{await api('/api/workspace','POST',{id:$('workspaceSelect').value});location.reload();}catch(err){notice(err.message,true);}};
action('logoutBtn',async()=>{await api('/api/logout','POST',{});location.href='/login';});
function submitForm(id,fn){$(id).onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await fn();}catch(err){notice(err.message,true);}finally{b.disabled=false;}};}
submitForm('accountForm',async()=>{await api('/api/account','POST',{username:$('accountUsername').value,current_password:$('accountCurrent').value,password:$('accountPassword').value});$('accountCurrent').value='';$('accountPassword').value='';await refresh();notice('Account updated. Other sessions must sign in again.');});
submitForm('createUserForm',async()=>{await api('/api/users','POST',{username:$('createUsername').value,password:$('createPassword').value});$('createPassword').value='';notice('Account created with a separate workspace. Grant shared access below if needed.');});
submitForm('shareForm',async()=>{await api('/api/share','POST',{username:$('shareUsername').value,role:$('shareRole').value});await refresh();notice('Workspace access updated.');});
submitForm('documentTypeForm',async()=>{await api('/api/document-types','POST',{name:$('newDocType').value,instructions:$('newDocInstructions').value});await refresh();$('docCategory').value=$('newDocType').value.trim();$('ruleCategory').value=$('newDocType').value.trim();clearStudio();fillRules();notice('Document type added. Its instructions are available in Profile & settings.');});
submitForm('storageForm',async()=>{await api('/api/settings','POST',{storage:{mode:$('storageMode').value,destination:$('storageDestination').value.trim(),auto_sync:$('storageAuto').checked}});await refresh();notice('Storage preference saved. Use Back up now to verify the destination.');});
action('checkStorage',async()=>{const r=await api('/api/storage/connections');$('storageConnections').textContent=r.available?'Configured remotes: '+(r.remotes.join(', ')||'None. Run rclone config first.') : r.message;});
action('syncStorage',async()=>{const r=await runTask('/api/storage/sync',{});notice(r.message);});
action('trainingExport',async()=>{const r=await fetch('/api/training-export',{method:'POST',headers:{'X-CSRF-Token':csrf}});if(!r.ok){const d=await r.json();throw Error(d.error);}download(await r.text(),'approved_training_examples.jsonl');});
$('notificationList').onclick=async e=>{const b=e.target.closest('button');if(!b)return;try{const id=b.dataset.notification||b.dataset.read;if(!id)return;await api('/api/notifications/read','POST',{id});if(b.dataset.notification){if(b.dataset.space!==state.active_workspace){await api('/api/workspace','POST',{id:b.dataset.space});await refresh(true);clearStudio();}openTab('jobs');await editJob(b.dataset.job);}await refresh();}catch(err){notice(err.message,true);}};

async function componentStatus(){const r=await api('/api/runtime/status');$('runtimeStatus').textContent=`Tectonic: ${r.tectonic?'ready':'not installed'} · Local engine: ${r.running?'running':r.ollama?'installed, stopped':'not installed'} · Trainer: ${r.trainer?'ready':'not installed'}`;$('localModels').textContent='Downloaded models: '+(r.models.map(m=>m.name).join(', ')||'none');}
for(const [id,kind] of [['installPdf','tectonic'],['installBrowserPdf','browser'],['installOllama','ollama'],['installTrainer','trainer']])action(id,async()=>{const r=await runTask('/api/runtime/install',{kind});await componentStatus();notice(r.message);});
action('savePdfEngine',async()=>{await api('/api/settings','POST',{pdf_engine:$('pdfEngine').value,pdf_remote_consent:$('pdfRemoteConsent').checked,pdf_browser_fallback:$('pdfBrowserFallback').checked});await refresh();notice('PDF engine saved.');});
action('pdfSetupStatus',componentStatus);
action('startOllama',async()=>{const r=await runTask('/api/runtime/start',{});await componentStatus();notice(r.message);});
action('downloadModel',async()=>{const r=await runTask('/api/runtime/pull',{model:$('pullModel').value.trim()});await refresh(true);await componentStatus();notice(r.message);});
async function learningStatus(){const r=await api('/api/learning/status');$('learningExamples').innerHTML=r.examples.map(d=>`<details class="row"><summary><input type="checkbox" data-training-id="${d.id}"> ${esc(d.category)} · ${esc(d.created)} · ${d.content.length} characters</summary><strong>Prompt</strong><pre>${esc(d.prompt)}</pre><strong>Approved answer</strong><pre>${esc(d.content)}</pre></details>`).join('')||'<p>No approved documents with generation prompts yet. Generate, edit and approve documents in Application studio first.</p>';$('learningRuns').innerHTML=r.runs.map(v=>`<div class="panel"><strong>${esc(v.created)} · ${esc(v.state)} ${r.active===v.id?'· ACTIVE':''}</strong><p>${esc(v.base_model)} · ${v.examples} examples</p><pre>${esc(JSON.stringify(v.metrics||v.error||{},null,2))}</pre>${v.state==='ready'?`<button data-model-test="${v.id}">Test this version</button> <button data-model-activate="${v.id}" ${v.eligible?'':'disabled'}>Activate this version</button>`:v.state==='running'?`<button data-model-cancel="${v.id}">Cancel training</button>`:''}</div>`).join('');}
action('refreshLearning',learningStatus);
action('trainModel',async()=>{const ids=Array.from(document.querySelectorAll('[data-training-id]:checked')).map(x=>x.dataset.trainingId);await runTask('/api/learning/train',{ids,base:$('trainingBase').value.trim(),epochs:Number($('trainingEpochs').value)});await learningStatus();notice('Training complete. Review metrics and test a response before activating.');});
action('rollbackModel',async()=>{const r=await api('/api/learning/rollback','POST',{});await refresh(true);await learningStatus();notice(r.message);});
$('learningRuns').onclick=async e=>{const b=e.target.closest('button');if(!b)return;b.disabled=true;try{if(b.dataset.modelTest){if(!$('learningPrompt').value.trim())throw Error('Enter a test prompt first.');const r=await runTask('/api/learning/preview',{id:b.dataset.modelTest,prompt:$('learningPrompt').value});$('learningSample').textContent=r.text;}else if(b.dataset.modelActivate){const r=await api('/api/learning/activate','POST',{id:b.dataset.modelActivate});await refresh(true);notice(r.message);}else if(b.dataset.modelCancel)await api('/api/learning/cancel','POST',{id:b.dataset.modelCancel});await learningStatus();}catch(err){notice(err.message,true);}finally{b.disabled=false;}};

refresh(true).catch(err=>notice(err.message,true));

setInterval(()=>{if(state&&!$('search').hidden&&!universityDirty&&state.universities.some(u=>u.discovery_status==='queued'))refresh().catch(e=>notice(e.message,true));},6000);
